<script setup lang="ts">
import { computed, ref, watch, defineAsyncComponent, provide } from 'vue'
import { type Locale, messages, categoryKeys } from './i18n'

const DielineTool = defineAsyncComponent(() => import('./integrations/dieline/DielineTool.vue'))
const PalletOptimizer = defineAsyncComponent(() => import('./integrations/pallet/PalletOptimizer.vue'))

type ToolId='cbm'|'container'|'freight'|'cost'|'labels'|'packing'|'audit'|'nesting'|'warehouse'|'invoice'|'units'|'dieline'|'pallet'
type Cargo={sku:string,length:number,width:number,height:number,weight:number,qty:number,price:number}
const locale=ref<Locale>('en')
provide('hostLocale', locale)
const t=(key:string)=>messages[locale.value][key]||key
const catLabel=(cat:string)=>t(categoryKeys[cat]||cat)
const titles:Record<ToolId,[string,string,string]>={
 cbm:['CBM & volumetric weight','CBM / 体积重计算','CBM / 부피중량 계산'],container:['Container loading','集装箱装柜估算','컨테이너 적재 계산'],freight:['Freight comparison','物流运费比较','운임 비교'],cost:['Packaging cost','包装物流成本','포장·물류 비용'],labels:['Shipping labels','箱唛与标签','배송 라벨'],packing:['Packing list','装箱单生成','패킹리스트'],audit:['Shipment audit','出货资料核对','출하 자료 검증'],nesting:['Sheet nesting','纸板排版优化','원지 배치 최적화'],warehouse:['Warehouse capacity','仓库容量规划','창고 용량 계획'],invoice:['Commercial invoice','商业发票生成','상업송장 생성'],units:['Unit converter','单位换算','단위 변환'],dieline:['Dieline CAD','参数化刀版 CAD','칼선 CAD'],pallet:['Pallet optimizer','卡板装载优化','팔레트 적재 최적화']}
const descriptions:Record<ToolId,[string,string,string]>={
 cbm:['Volume, gross weight, chargeable weight','体积、毛重、计费重量','부피·총중량·운임중량'],container:['20GP / 40GP / 40HQ estimates','20GP / 40GP / 40HQ 容量估算','20GP / 40GP / 40HQ 용량'],freight:['Compare configurable sample rates','可配置示例费率比较','설정 가능한 예시 운임 비교'],cost:['Material, labor and shipping totals','材料、人工与运输费用汇总','자재·인건비·운송비 합계'],labels:['Printable carton marks and CSV','可打印箱唛与 CSV','인쇄용 카톤 마크'],packing:['Editable shipment list with CSV export','装箱清单与 CSV 导出','패킹리스트 CSV 내보내기'],audit:['Find quantity, weight and value mismatches','核对数量、重量、金额差异','수량·중량·금액 검증'],nesting:['Rectangle sheet layout preview','矩形纸板排版与利用率','직사각형 원지 배치'],warehouse:['Racking volume and floor use estimates','货架容量与地面利用率估算','랙 용량·면적 활용 추정'],invoice:['Printable commercial invoice','可打印商业发票','인쇄용 상업송장'],units:['Length, mass and volume conversions','长度、质量与体积单位换算','길이·무게·부피 단위 변환'],dieline:['2D dieline, 3D fold preview and export','2D 刀版、3D 折叠预览与导出','2D 칼선·3D 접기 미리보기·내보내기'],pallet:['3D mixed-SKU pallet loading planner','三维多规格卡板装载规划','3D 다규격 팔레트 적재 계획']}
const idx=computed(()=>locale.value==='en'?0:locale.value==='zh'?1:2)
const tools:{id:ToolId;icon:string;category:string;paid:boolean}[]=[
 {id:'cbm',icon:'◫',category:'Freight',paid:false},{id:'container',icon:'▣',category:'Loading',paid:true},{id:'freight',icon:'⇄',category:'Freight',paid:false},{id:'cost',icon:'$',category:'Packaging',paid:false},{id:'labels',icon:'▤',category:'Documents',paid:false},{id:'packing',icon:'☷',category:'Documents',paid:false},{id:'audit',icon:'✓',category:'Documents',paid:true},{id:'nesting',icon:'▦',category:'Packaging',paid:true},{id:'warehouse',icon:'▥',category:'Warehouse',paid:false},{id:'invoice',icon:'▧',category:'Documents',paid:false},{id:'units',icon:'↔',category:'Freight',paid:false},{id:'dieline',icon:'◇',category:'Packaging',paid:true},{id:'pallet',icon:'▰',category:'Loading',paid:true}
]
const active=ref<ToolId|null>(null),search=ref(''),category=ref('All'),showData=ref(false),mobileNav=ref(false),showPricing=ref(false)
const categories=['All','Packaging','Loading','Freight','Documents','Warehouse']
const visibleTools=computed(()=>tools.filter(x=>(category.value==='All'||x.category===category.value)&&(`${titles[x.id].join(' ')} ${descriptions[x.id].join(' ')}`.toLowerCase().includes(search.value.toLowerCase()))))
const sample=():Cargo[]=>[{sku:'SKU-A / Gift box',length:42,width:32,height:28,weight:7.5,qty:120,price:12.5},{sku:'SKU-B / Accessories',length:36,width:28,height:22,weight:5.2,qty:80,price:8.9},{sku:'SKU-C / Parts',length:52,width:38,height:34,weight:11.4,qty:40,price:24}]
const cargo=ref<Cargo[]>(sample())
const n=(v:unknown)=>Math.max(0,Number(v)||0)
const volume=(c:Cargo)=>n(c.length)*n(c.width)*n(c.height)/1e6
const cbm=computed(()=>cargo.value.reduce((s,c)=>s+volume(c)*n(c.qty),0))
const gross=computed(()=>cargo.value.reduce((s,c)=>s+n(c.weight)*n(c.qty),0))
const qty=computed(()=>cargo.value.reduce((s,c)=>s+n(c.qty),0))
const goodsValue=computed(()=>cargo.value.reduce((s,c)=>s+n(c.price)*n(c.qty),0))
const format=(v:number,d=2)=>Number.isFinite(v)?v.toLocaleString(locale.value==='ko'?'ko-KR':locale.value==='zh'?'zh-CN':'en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—'
const addCargo=()=>cargo.value.push({sku:`SKU-${cargo.value.length+1}`,length:40,width:30,height:25,weight:5,qty:10,price:10})
const reset=()=>{cargo.value=sample();auditQty.value=qty.value;auditGross.value=gross.value;auditValue.value=goodsValue.value}
const download=(filename:string,content:string,mime='text/csv;charset=utf-8')=>{const blob=new Blob(['\ufeff',content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const csv=(rows:(string|number)[][])=>rows.map(r=>r.map(x=>`"${String(x).replace(/"/g,'""')}"`).join(',')).join('\r\n')
const exportCargo=()=>download('cargo-data.csv',csv([[t('colSku'),t('lengthCm'),t('widthCm'),t('heightCm'),t('weightKg'),t('colQty'),t('unitPriceUsd')],...cargo.value.map(c=>[c.sku,c.length,c.width,c.height,c.weight,c.qty,c.price])]))
const dimDivisor=ref(6000),containerType=ref('40HQ'),freightAir=ref(4.2),freightSea=ref(95),freightExpress=ref(6.8),packingUnit=ref(1.1),laborUnit=ref(.22),palletCost=ref(18),palletCount=ref(4),shippingCost=ref(350),margin=ref(15)
const cbmDim=computed(()=>cargo.value.reduce((s,c)=>s+n(c.length)*n(c.width)*n(c.height)/n(dimDivisor.value)*n(c.qty),0))
const containerTypes=[{id:'20GP',l:589,w:235,h:239,max:28000},{id:'40GP',l:1203,w:235,h:239,max:26500},{id:'40HQ',l:1203,w:235,h:269,max:26500}]
const container=computed(()=>containerTypes.find(x=>x.id===containerType.value)!)
const containerVol=computed(()=>container.value.l*container.value.w*container.value.h/1e6)
const volUtil=computed(()=>containerVol.value?cbm.value/containerVol.value*100:0)
const weightUtil=computed(()=>container.value.max?gross.value/container.value.max*100:0)
const shippingOptions=computed(()=>[{id:'shipExpress',price:Math.max(gross.value,cbmDim.value)*n(freightExpress.value)},{id:'shipAir',price:Math.max(gross.value,cbmDim.value)*n(freightAir.value)},{id:'shipSeaLcl',price:cbm.value*n(freightSea.value)}])
const costBase=computed(()=>qty.value*(n(packingUnit.value)+n(laborUnit.value))+n(palletCount.value)*n(palletCost.value)+n(shippingCost.value))
const costFinal=computed(()=>costBase.value*(1+n(margin.value)/100))
const shipper=ref('YOUR COMPANY'),consignee=ref('CUSTOMER NAME'),po=ref('PO-2026-001'),currency=ref('USD'),invoiceNo=ref('INV-2026-001')
const auditQty=ref(240),auditGross=ref(1772),auditValue=ref(3172)
const auditResults=computed(()=>[{labelKey:'auditQty',expected:qty.value,actual:n(auditQty.value),unit:'pcs'},{labelKey:'auditGross',expected:gross.value,actual:n(auditGross.value),unit:'kg'},{labelKey:'auditGoodsValue',expected:goodsValue.value,actual:n(auditValue.value),unit:'USD'}])
const sheetW=ref(1200),sheetH=ref(900),partW=ref(260),partH=ref(190),kerf=ref(5),parts=ref(18),allowRotate=ref(true)
const nesting=computed(()=>{const W=n(sheetW.value),H=n(sheetH.value),gap=n(kerf.value),a=n(partW.value),b=n(partH.value);const arrangements=[{w:a,h:b,rot:false},...(allowRotate.value?[{w:b,h:a,rot:true}]:[])].map(o=>{const cols=Math.floor((W+gap)/(o.w+gap)),rows=Math.floor((H+gap)/(o.h+gap));return {...o,cols:Math.max(0,cols),rows:Math.max(0,rows),capacity:Math.max(0,cols*rows)}});arrangements.sort((x,y)=>y.capacity-x.capacity);const best=arrangements[0];return {...best,sheets:best.capacity?Math.ceil(n(parts.value)/best.capacity):0,util:W*H>0&&best.capacity?Math.min(n(parts.value),best.capacity)*a*b/(W*H)*100:0}})
const warehouseL=ref(30),warehouseW=ref(20),warehouseH=ref(6),aislePct=ref(35),rackLevels=ref(3),rackCapacity=ref(2.5)
const usableArea=computed(()=>n(warehouseL.value)*n(warehouseW.value)*(1-Math.min(100,n(aislePct.value))/100))
const warehousePositions=computed(()=>Math.floor(usableArea.value/Math.max(.1,n(rackCapacity.value)))*Math.max(1,Math.floor(n(rackLevels.value))))
const unitType=ref('length'),unitValue=ref(100),unitFrom=ref('cm'),unitTo=ref('in')
const unitDefs:Record<string,Record<string,number>>={length:{mm:.001,cm:.01,m:1,in:.0254,ft:.3048},mass:{g:.001,kg:1,lb:.45359237},volume:{cm3:.000001,L:.001,m3:1,ft3:.028316846592}}
const converted=computed(()=>n(unitValue.value)*(unitDefs[unitType.value]?.[unitFrom.value]||1)/(unitDefs[unitType.value]?.[unitTo.value]||1))
watch(unitType,()=>{const keys=Object.keys(unitDefs[unitType.value]);unitFrom.value=keys[0];unitTo.value=keys[1]})
const pricingPlans=computed(()=>[
 {nameKey:'planFree',price:'$0',descKey:'planFreeDesc',features:['planFeatBasic','planFeatLocal','planFeatCsv']},
 {nameKey:'planPro',price:'$12',descKey:'planProDesc',features:['planFeatOpt','planFeatHistory','planFeatCad']},
 {nameKey:'planBusiness',price:'$39',descKey:'planBusinessDesc',features:['planFeatSeats','planFeatBatch','planFeatPriority']},
])
const exportLabels=()=>download('shipping-marks.csv',csv([[t('poLabel'),t('shipper'),t('consignee'),t('csvCarton'),t('colSku')],...cargo.value.map((c,i)=>[po.value,shipper.value,consignee.value,i+1,c.sku])]))
const exportPacking=()=>download('packing-list.csv',csv([[t('colSku'),t('quantity'),t('colGrossKg'),t('colCbm')],...cargoRows.value.map(c=>[c.sku,c.qty,c.totalWeight,c.cbm]),[t('total'),qty.value,gross.value,cbm.value]]))
const exportInvoice=()=>download('commercial-invoice.csv',csv([[t('invoiceLabel'),invoiceNo.value],[t('seller'),shipper.value],[t('buyer'),consignee.value],[t('colSku'),t('colQty'),t('unitPrice'),t('total')],...cargoRows.value.map(c=>[c.sku,c.qty,c.price,c.totalPrice]),[t('total'),'','',goodsValue.value]]))
const openTool=(id:ToolId)=>{active.value=id;showData.value=false;mobileNav.value=false;showPricing.value=false;window.scrollTo({top:0,behavior:'smooth'})}
const back=()=>{active.value=null;showData.value=false;showPricing.value=false;mobileNav.value=false;window.scrollTo({top:0,behavior:'smooth'})}
const printDoc=()=>window.print()
const cargoRows=computed(()=>cargo.value.map(c=>({...c,cbm:volume(c)*n(c.qty),totalWeight:n(c.weight)*n(c.qty),totalPrice:n(c.price)*n(c.qty)})))
const activeCategory=computed(()=>tools.find(x=>x.id===active.value)?.category||'')
const activePaid=computed(()=>!!tools.find(x=>x.id===active.value)?.paid)
</script>

<template>
<div class="shell">
  <aside class="sidebar" :class="{open:mobileNav}">
    <div class="brand" @click="back"><div class="brand-mark">P<span>·</span></div><div><strong>PackFlow</strong><small>{{t('brandTag')}}</small></div></div>
    <div class="sidebar-caption">{{t('workspace')}}</div>
    <button class="nav-link" :class="{selected:!active&&!showData&&!showPricing}" @click="back"><span>▦</span>{{t('overview')}}</button>
    <button class="nav-link" :class="{selected:showData}" @click="showData=true;active=null;showPricing=false;mobileNav=false"><span>▤</span>{{t('shared')}}</button>
    <div class="sidebar-caption">{{t('categories')}}</div>
    <button v-for="cat in categories.slice(1)" :key="cat" class="nav-link" :class="{selected:active&&tools.find(x=>x.id===active)?.category===cat}" @click="category=cat;back()"><span>{{cat==='Packaging'?'◇':cat==='Loading'?'▣':cat==='Freight'?'⇄':cat==='Documents'?'☷':'▥'}}</span>{{catLabel(cat)}}</button>
    <div class="sidebar-bottom"><div class="plan-icon">✦</div><strong>{{t('sidebarTitle')}}</strong><p>{{t('sidebarDesc')}}</p><button class="side-plan" @click="showPricing=true;active=null;showData=false">{{t('pricing')}} ↗</button></div>
  </aside>
  <div class="main-wrap">
    <header class="topbar"><button class="hamburger" @click="mobileNav=!mobileNav">☰</button><div class="breadcrumbs"><span @click="back">{{t('home')}}</span><span class="slash">/</span><strong>{{active?titles[active][idx]:showPricing?t('pricing'):showData?t('shared'):t('tools')}}</strong></div><div class="top-actions"><span class="live-dot"></span><span class="top-status">{{t('status')}}</span><select v-model="locale" class="language"><option value="en">EN</option><option value="zh">中文</option><option value="ko">한국어</option></select><button class="login" @click="showPricing=true;active=null;showData=false">{{t('sign')}}</button></div></header>
    <main class="main">
      <template v-if="!active&&!showData&&!showPricing">
        <section class="hero"><div class="hero-content"><div class="eyebrow">✦ {{t('heroEyebrow')}}</div><h1>{{t('hero')}}</h1><p>{{t('subtitle')}}</p><button class="hero-btn" @click="category='All';$nextTick(()=>document.getElementById('tool-grid')?.scrollIntoView({behavior:'smooth'}))">{{t('try')}} <span>↗</span></button><div class="hero-pills"><span>✓ 13 {{t('toolsCount')}}</span><span>✓ EN / 中文 / 한국어</span><span>✓ {{t('noInstall')}}</span></div></div><div class="hero-art"><div class="art-grid"></div><div class="floating-card card-a"><span>◫</span><div><small>{{t('volumeCalculated')}}</small><strong>{{format(cbm)}} m³</strong></div></div><div class="floating-card card-b"><span>▣</span><div><small>{{t('loadingAnalysis')}}</small><strong>{{format(volUtil,1)}}% {{t('capacityLabel')}}</strong></div></div><div class="art-box box-one"></div><div class="art-box box-two"></div><div class="art-box box-three"></div></div></section>
        <div class="stats"><div><span class="stat-symbol">◫</span><strong>13</strong><small>{{t('ready')}}</small></div><div><span class="stat-symbol">◇</span><strong>2</strong><small>{{t('tagPro')}}</small></div><div><span class="stat-symbol">◎</span><strong>3</strong><small>{{t('languages')}}</small></div><div><span class="stat-symbol">↗</span><strong>100%</strong><small>{{t('browserBased')}}</small></div></div>
        <div class="section-head" id="tool-grid"><div><div class="eyebrow dark">{{t('exploreCreate')}}</div><h2>{{t('library')}}</h2><p>{{t('librarySub')}}</p></div><div class="search-wrap"><span>⌕</span><input v-model="search" :placeholder="t('search')" /></div></div>
        <div class="chips"><button v-for="cat in categories" :key="cat" :class="{active:category===cat}" @click="category=cat">{{catLabel(cat)}}</button></div>
        <div class="tool-grid"><button v-for="tool in visibleTools" :key="tool.id" class="tool-card" @click="openTool(tool.id)"><div class="tool-card-top"><span class="tool-icon" :class="tool.category.toLowerCase()">{{tool.icon}}</span><span class="tag">{{tool.paid?t('tagPro'):t('tagFree')}}</span></div><h3>{{titles[tool.id][idx]}}</h3><p>{{descriptions[tool.id][idx]}}</p><div class="tool-card-bottom"><span>{{catLabel(tool.category)}}</span><strong>↗</strong></div></button></div><p v-if="!visibleTools.length" class="empty">{{t('empty')}}</p>
        <div class="bottom-banner"><div><span class="eyebrow">{{t('bannerEyebrow')}}</span><h2>{{t('bannerTitle')}}</h2><p>{{t('bannerDesc')}}</p></div><button @click="showPricing=true">{{t('pricing')}} →</button></div>
      </template>
      <template v-else-if="showPricing">
        <div class="page-heading"><button class="back" @click="back">← {{t('all')}}</button><div class="eyebrow dark">{{t('pricingEyebrow')}}</div><h1>{{t('pricing')}}</h1><p>{{t('billing')}}</p></div><div class="pricing-grid"><div v-for="plan in pricingPlans" :key="plan.nameKey" class="price-card"><h3>{{t(plan.nameKey)}}</h3><strong>{{plan.price}}<small> {{t('perMonth')}}</small></strong><p>{{t(plan.descKey)}}</p><ul><li v-for="f in plan.features" :key="f">✓ {{t(f)}}</li></ul><button disabled>{{t('comingLater')}}</button></div></div>
      </template>
      <template v-else-if="showData">
        <div class="page-heading"><button class="back" @click="back">← {{t('all')}}</button><div class="eyebrow dark">{{t('sharedEyebrow')}}</div><h1>{{t('shared')}}</h1><p>{{t('sharedDesc')}}</p></div><div class="panel"><div class="panel-heading"><h3>{{t('cargoItems')}}</h3><div class="btn-row"><button class="btn-secondary" @click="reset">{{t('reset')}}</button><button class="btn-secondary" @click="exportCargo">{{t('export')}}</button><button class="btn-primary" @click="addCargo">+ {{t('add')}}</button></div></div><div class="table-scroll"><table><thead><tr><th>{{t('name')}}</th><th>{{t('length')}} cm</th><th>{{t('width')}} cm</th><th>{{t('height')}} cm</th><th>{{t('weight')}} kg</th><th>{{t('quantity')}}</th><th>{{t('price')}} USD</th><th></th></tr></thead><tbody><tr v-for="(c,i) in cargo" :key="i"><td><input v-model="c.sku" class="cell-name" /></td><td><input v-model.number="c.length" type="number" min="0" /></td><td><input v-model.number="c.width" type="number" min="0" /></td><td><input v-model.number="c.height" type="number" min="0" /></td><td><input v-model.number="c.weight" type="number" min="0" step="0.1" /></td><td><input v-model.number="c.qty" type="number" min="0" step="1" /></td><td><input v-model.number="c.price" type="number" min="0" step="0.1" /></td><td><button class="remove" @click="cargo.splice(i,1)">×</button></td></tr></tbody></table></div><div class="data-summary"><span>{{qty}} {{t('pcs')}}</span><span>{{format(cbm)}} m³</span><span>{{format(gross)}} kg</span><span>${{format(goodsValue)}}</span></div></div>
      </template>
      <template v-else-if="active">
        <div class="page-heading"><button class="back" @click="back">← {{t('all')}}</button><div class="eyebrow dark">{{catLabel(activeCategory)}} / {{activePaid?t('proTool'):t('freeTool')}}</div><h1>{{titles[active][idx]}}</h1><p>{{descriptions[active][idx]}}</p></div>
        <DielineTool v-if="active==='dieline'" />
        <PalletOptimizer v-else-if="active==='pallet'" />
        <template v-else>
          <div class="tool-layout"><div class="tool-settings"><div class="panel"><div class="panel-heading"><h3>{{t('settings')}}</h3><span class="small-badge">{{t('live')}}</span></div>
            <template v-if="active==='cbm'"><label class="field">{{t('dimDivisor')}}<select v-model.number="dimDivisor"><option :value="5000">5000</option><option :value="6000">6000</option><option :value="4000">4000</option></select></label><p class="field-hint">{{t('dimDivisorHint')}}</p></template>
            <template v-if="active==='container'"><label class="field">{{t('containerType')}}<select v-model="containerType"><option v-for="x in containerTypes" :key="x.id">{{x.id}}</option></select></label><p class="field-hint">{{t('containerHint')}}</p></template>
            <template v-if="active==='freight'"><label class="field">{{t('freightExpressRate')}}<input v-model.number="freightExpress" type="number" min="0" step=".1" /></label><label class="field">{{t('freightAirRate')}}<input v-model.number="freightAir" type="number" min="0" step=".1" /></label><label class="field">{{t('freightSeaRate')}}<input v-model.number="freightSea" type="number" min="0" step="1" /></label><label class="field">{{t('dimDivisor')}}<select v-model.number="dimDivisor"><option :value="5000">5000</option><option :value="6000">6000</option></select></label><p class="field-hint">{{t('freightHint')}}</p></template>
            <template v-if="active==='cost'"><label class="field">{{t('costPackaging')}}<input v-model.number="packingUnit" type="number" min="0" step=".1" /></label><label class="field">{{t('costLabor')}}<input v-model.number="laborUnit" type="number" min="0" step=".1" /></label><label class="field">{{t('costPallets')}}<input v-model.number="palletCount" type="number" min="0" /></label><label class="field">{{t('costPalletCost')}}<input v-model.number="palletCost" type="number" min="0" /></label><label class="field">{{t('costShipping')}}<input v-model.number="shippingCost" type="number" min="0" /></label><label class="field">{{t('costMarkup')}}<input v-model.number="margin" type="number" min="0" /></label></template>
            <template v-if="active==='labels'||active==='packing'||active==='invoice'"><label class="field">{{t('shipper')}}<input v-model="shipper" /></label><label class="field">{{t('consignee')}}<input v-model="consignee" /></label><label class="field">{{t('poNumber')}}<input v-model="po" /></label><label v-if="active==='invoice'" class="field">{{t('invoiceNumber')}}<input v-model="invoiceNo" /></label><label v-if="active==='invoice'" class="field">{{t('currency')}}<input v-model="currency" /></label><button class="btn-primary full" @click="printDoc">{{t('printPdf')}} ↗</button></template>
            <template v-if="active==='audit'"><label class="field">{{t('declaredQty')}}<input v-model.number="auditQty" type="number" min="0" /></label><label class="field">{{t('declaredGross')}}<input v-model.number="auditGross" type="number" min="0" /></label><label class="field">{{t('declaredValue')}}<input v-model.number="auditValue" type="number" min="0" /></label><button class="btn-secondary full" @click="auditQty=qty;auditGross=gross;auditValue=goodsValue">{{t('matchComputed')}}</button></template>
            <template v-if="active==='nesting'"><label class="field">{{t('sheetWidth')}}<input v-model.number="sheetW" type="number" min="1" /></label><label class="field">{{t('sheetHeight')}}<input v-model.number="sheetH" type="number" min="1" /></label><label class="field">{{t('partWidth')}}<input v-model.number="partW" type="number" min="1" /></label><label class="field">{{t('partHeight')}}<input v-model.number="partH" type="number" min="1" /></label><label class="field">{{t('gapMm')}}<input v-model.number="kerf" type="number" min="0" /></label><label class="field">{{t('partsRequired')}}<input v-model.number="parts" type="number" min="0" /></label><label class="toggle"><input v-model="allowRotate" type="checkbox" /> {{t('allowRotate')}}</label><p class="field-hint">{{t('nestingHint')}}</p></template>
            <template v-if="active==='warehouse'"><label class="field">{{t('warehouseLength')}}<input v-model.number="warehouseL" type="number" min="0" /></label><label class="field">{{t('warehouseWidth')}}<input v-model.number="warehouseW" type="number" min="0" /></label><label class="field">{{t('warehouseHeight')}}<input v-model.number="warehouseH" type="number" min="0" /></label><label class="field">{{t('aislePct')}}<input v-model.number="aislePct" type="number" min="0" max="100" /></label><label class="field">{{t('rackLevels')}}<input v-model.number="rackLevels" type="number" min="1" /></label><label class="field">{{t('floorPerPosition')}}<input v-model.number="rackCapacity" type="number" min="0.1" step="0.1" /></label></template>
            <template v-if="active==='units'"><label class="field">{{t('quantityType')}}<select v-model="unitType"><option value="length">{{t('unitLength')}}</option><option value="mass">{{t('unitMass')}}</option><option value="volume">{{t('unitVolume')}}</option></select></label><label class="field">{{t('value')}}<input v-model.number="unitValue" type="number" /></label><label class="field">{{t('from')}}<select v-model="unitFrom"><option v-for="u in Object.keys(unitDefs[unitType])" :key="u">{{u}}</option></select></label><label class="field">{{t('to')}}<select v-model="unitTo"><option v-for="u in Object.keys(unitDefs[unitType])" :key="u">{{u}}</option></select></label></template>
          </div><div v-if="!['nesting','warehouse','units'].includes(active)" class="mini-panel"><span>▤</span><div><strong>{{qty}} {{t('items')}} · {{format(cbm)}} m³</strong><p>{{t('sharedDesc')}}</p></div><button @click="showData=true;active=null">{{t('edit')}} ↗</button></div></div>
          <div class="tool-output"><div class="panel output-panel"><div class="panel-heading"><h3>{{t('results')}}</h3><span class="small-badge light">{{t('autoUpdated')}}</span></div>
            <template v-if="active==='cbm'"><div class="metric-grid"><div class="metric primary"><span>{{t('totalCbm')}}</span><strong>{{format(cbm,3)}}<small> m³</small></strong></div><div class="metric"><span>{{t('grossWeight')}}</span><strong>{{format(gross)}}<small> kg</small></strong></div><div class="metric"><span>{{t('volumetricWeight')}}</span><strong>{{format(cbmDim)}}<small> kg</small></strong></div><div class="metric"><span>{{t('chargeableWeight')}}</span><strong>{{format(Math.max(gross,cbmDim))}}<small> kg</small></strong></div></div><div class="table-scroll"><table><thead><tr><th>{{t('colSku')}}</th><th>{{t('colQty')}}</th><th>{{t('colCbm')}}</th><th>{{t('colGrossKg')}}</th></tr></thead><tbody><tr v-for="c in cargoRows" :key="c.sku"><td>{{c.sku}}</td><td>{{c.qty}}</td><td>{{format(c.cbm,3)}}</td><td>{{format(c.totalWeight)}}</td></tr></tbody></table></div></template>
            <template v-if="active==='container'"><div class="metric-grid"><div class="metric primary"><span>{{t('volumeUtil')}}</span><strong>{{format(volUtil,1)}}<small>%</small></strong></div><div class="metric"><span>{{t('payloadUtil')}}</span><strong>{{format(weightUtil,1)}}<small>%</small></strong></div><div class="metric"><span>{{t('nominalVolume')}}</span><strong>{{format(containerVol)}}<small> m³</small></strong></div><div class="metric"><span>{{t('maxPayload')}}</span><strong>{{format(container.max,0)}}<small> kg</small></strong></div></div><div class="progress-label">{{t('volume')}} <strong>{{format(volUtil,1)}}%</strong></div><div class="progress"><div :style="{width:Math.min(100,volUtil)+'%'}"></div></div><div class="progress-label">{{t('weight')}} <strong>{{format(weightUtil,1)}}%</strong></div><div class="progress"><div class="weight-bar" :style="{width:Math.min(100,weightUtil)+'%'}"></div></div><div class="container-visual"><div class="container-outline"><div v-for="i in Math.min(90,Math.round(volUtil/100*90))" :key="i" class="container-cube"></div></div></div><p class="field-hint">{{t('containerVisualHint')}}</p><div v-if="volUtil>100||weightUtil>100" class="alert">⚠ {{t('capacityExceeded')}}</div></template>
            <template v-if="active==='freight'"><div class="metric-grid"><div class="metric primary"><span>{{t('chargeableWeight')}}</span><strong>{{format(Math.max(gross,cbmDim))}}<small> kg</small></strong></div><div class="metric"><span>{{t('totalVolume')}}</span><strong>{{format(cbm)}}<small> m³</small></strong></div></div><div class="freight-list"><div v-for="o in shippingOptions" :key="o.id"><div><strong>{{t(o.id)}}</strong><small>{{t('illustrativeEstimate')}}</small></div><strong>${{format(o.price)}}</strong></div></div></template>
            <template v-if="active==='cost'"><div class="metric-grid"><div class="metric primary"><span>{{t('estimatedTotalMarkup')}}</span><strong>${{format(costFinal)}}</strong></div><div class="metric"><span>{{t('costPerItem')}}</span><strong>${{format(qty?costFinal/qty:0)}}</strong></div></div><div class="cost-lines"><div><span>{{t('linePackaging')}}</span><strong>${{format(qty*packingUnit)}}</strong></div><div><span>{{t('lineLabor')}}</span><strong>${{format(qty*laborUnit)}}</strong></div><div><span>{{t('linePallets')}}</span><strong>${{format(palletCount*palletCost)}}</strong></div><div><span>{{t('lineFreight')}}</span><strong>${{format(shippingCost)}}</strong></div><div class="bold"><span>{{t('subtotal')}}</span><strong>${{format(costBase)}}</strong></div><div><span>{{t('markup')}}</span><strong>${{format(costFinal-costBase)}}</strong></div></div></template>
            <template v-if="active==='labels'"><div class="print-area"><div class="document-top">{{t('shippingMark')}}</div><div class="label-sheet"><strong>{{consignee}}</strong><span>{{t('fromLabel')}}: {{shipper}}</span><span>{{t('poLabel')}}: {{po}}</span><span>{{t('ctnNo')}}: 001 / {{qty}}</span><span>{{t('madeIn')}}: __________</span><div class="barcode">|||| ||| |||||| ||| || |||||</div><small>{{po}} / 001</small></div></div><button class="btn-secondary" @click="exportLabels">{{t('export')}}</button><p class="field-hint">{{t('labelsHint')}}</p></template>
            <template v-if="active==='packing'"><div class="print-area"><div class="document-top">{{t('packingList')}}</div><div class="doc-meta"><span>{{t('shipper')}}: {{shipper}}</span><span>{{t('consignee')}}: {{consignee}}</span><span>{{t('poLabel')}}: {{po}}</span></div><div class="table-scroll"><table><thead><tr><th>{{t('colSku')}}</th><th>{{t('colQty')}}</th><th>{{t('colGrossKg')}}</th><th>{{t('colCbm')}}</th></tr></thead><tbody><tr v-for="c in cargoRows" :key="c.sku"><td>{{c.sku}}</td><td>{{c.qty}}</td><td>{{format(c.totalWeight)}}</td><td>{{format(c.cbm,3)}}</td></tr></tbody><tfoot><tr><td>{{t('total')}}</td><td>{{qty}}</td><td>{{format(gross)}}</td><td>{{format(cbm,3)}}</td></tr></tfoot></table></div></div><button class="btn-secondary" @click="exportPacking">{{t('export')}}</button></template>
            <template v-if="active==='audit'"><div class="metric-grid"><div class="metric primary"><span>{{t('checksPassed')}}</span><strong>{{auditResults.filter(x=>Math.abs(x.actual-x.expected)<.011).length}}<small> / 3</small></strong></div><div class="metric"><span>{{t('checksFailed')}}</span><strong>{{auditResults.filter(x=>Math.abs(x.actual-x.expected)>=.011).length}}</strong></div></div><div class="audit-list"><div v-for="x in auditResults" :key="x.labelKey" :class="Math.abs(x.actual-x.expected)<.011?'pass':'fail'"><span>{{Math.abs(x.actual-x.expected)<.011?'✓':'!'}} {{t(x.labelKey)}}</span><span>{{t('expected')}} {{format(x.expected)}} {{x.unit}} / {{t('declared')}} {{format(x.actual)}} {{x.unit}}</span></div></div><p class="field-hint">{{t('auditHint')}}</p></template>
            <template v-if="active==='nesting'"><div class="metric-grid"><div class="metric primary"><span>{{t('partsPerSheet')}}</span><strong>{{nesting.capacity}}</strong></div><div class="metric"><span>{{t('sheetsNeeded')}}</span><strong>{{nesting.sheets||'—'}}</strong></div><div class="metric"><span>{{t('firstSheetUtil')}}</span><strong>{{format(nesting.util,1)}}<small>%</small></strong></div><div class="metric"><span>{{t('orientation')}}</span><strong>{{nesting.rot?'90°':'0°'}}</strong></div></div><div class="nesting-wrap"><div class="nesting-sheet" :style="{aspectRatio:`${Math.max(1,sheetW)}/${Math.max(1,sheetH)}`}"><div class="nesting-cells" :style="{gridTemplateColumns:`repeat(${Math.max(1,nesting.cols)},1fr)`,gridTemplateRows:`repeat(${Math.max(1,nesting.rows)},1fr)`}"><div v-for="i in Math.min(300,nesting.capacity,Math.max(0,parts))" :key="i" class="nesting-cell">{{i}}</div></div></div></div><p class="field-hint">{{t('nestingResultHint')}}</p></template>
            <template v-if="active==='warehouse'"><div class="metric-grid"><div class="metric primary"><span>{{t('usableStorage')}}</span><strong>{{format(usableArea)}}<small> m²</small></strong></div><div class="metric"><span>{{t('palletPositions')}}</span><strong>{{format(warehousePositions,0)}}</strong></div><div class="metric"><span>{{t('buildingVolume')}}</span><strong>{{format(warehouseL*warehouseW*warehouseH)}}<small> m³</small></strong></div><div class="metric"><span>{{t('grossFloorArea')}}</span><strong>{{format(warehouseL*warehouseW)}}<small> m²</small></strong></div></div><div class="warehouse-view"><div class="aisle">{{t('aisleOther')}}</div><div class="racks"><span v-for="i in 18" :key="i">▥</span></div></div><p class="field-hint">{{t('warehouseHint')}}</p></template>
            <template v-if="active==='invoice'"><div class="print-area"><div class="document-top">{{t('commercialInvoice')}}</div><div class="doc-meta"><span>{{t('invoiceLabel')}}: {{invoiceNo}}</span><span>{{t('poLabel')}}: {{po}}</span><span>{{t('seller')}}: {{shipper}}</span><span>{{t('buyer')}}: {{consignee}}</span></div><div class="table-scroll"><table><thead><tr><th>{{t('description')}}</th><th>{{t('colQty')}}</th><th>{{t('unitPrice')}} {{currency}}</th><th>{{t('total')}} {{currency}}</th></tr></thead><tbody><tr v-for="c in cargoRows" :key="c.sku"><td>{{c.sku}}</td><td>{{c.qty}}</td><td>{{format(c.price)}}</td><td>{{format(c.totalPrice)}}</td></tr></tbody><tfoot><tr><td colspan="3">{{t('total')}} {{currency}}</td><td>{{format(goodsValue)}}</td></tr></tfoot></table></div></div><button class="btn-secondary" @click="exportInvoice">{{t('export')}}</button><p class="field-hint">{{t('invoiceHint')}}</p></template>
            <template v-if="active==='units'"><div class="unit-answer"><small>{{t('convertedValue')}}</small><strong>{{format(converted,6)}}</strong><span>{{unitTo}}</span></div><div class="unit-formula">{{format(unitValue,4)}} {{unitFrom}} = {{format(converted,6)}} {{unitTo}}</div></template>
          </div><div class="hint-box">ⓘ {{t('disclaimer')}}</div></div></div>
        </template>
      </template>
    </main><footer class="footer"><span>{{t('footerCopy')}}</span><span>EN · 中文 · 한국어 &nbsp; | &nbsp; {{t('footerTagline')}}</span></footer>
  </div>
</div>
</template>
